function aiPage(){return `<div class="page page-transition">${pageTitle('NOVA INTELLIGENCE','智能工作台','从一个想法、一份文档或一个数据问题开始；AI 会把它整理成可以继续推进的成果。',`<button class="secondary" data-open-modal="new-workflow">${icon('plus',15)} 新建工作流</button>`)}<div class="chat-layout"><section class="panel chat-window"><div class="chat-header"><div class="ai-brand"><span class="ai-avatar">${icon('sparkles',20)}</span><div><strong style="font-size:13px;display:block">Nova 助手</strong><span class="small muted">上下文工作台 · 原型演示</span></div></div><div style="display:flex;align-items:center;gap:7px"><span class="tag good">${icon('sparkles',12)} 本地运行</span><button class="icon-btn" data-open-modal="model-picker" aria-label="选择模型">${icon('sliders',15)}</button><button class="icon-btn" data-toast="已开始新会话（演示）" aria-label="新会话">${icon('plus',15)}</button></div></div><div class="chat-messages" id="chatMessages"><div class="message"><div class="bubble-avatar">N</div><div class="bubble"><h4>你好，我是 Nova。</h4><p>可以直接告诉我你想完成什么，不必先写好提示词；我会帮你澄清目标、整理信息，并给出下一步建议。</p><div class="chips"><button class="chip" data-prompt="帮我梳理一个 AI 办公工具网站的核心需求和页面结构。" data-send-prompt>梳理产品需求 ${icon('arrow',12)}</button><button class="chip" data-prompt="请把一份长文档整理成摘要、关键结论和待办事项。" data-send-prompt>总结文档 ${icon('arrow',12)}</button><button class="chip" data-prompt="帮我规划一个从上传 Excel 到生成分析报告的工作流。" data-send-prompt>规划工作流 ${icon('arrow',12)}</button></div></div></div></div><form class="chat-compose" id="aiForm"><div class="compose-box"><button class="icon-btn" type="button" data-file-trigger aria-label="添加文件">${icon('plus',17)}</button><textarea id="aiInput" rows="1" placeholder="描述你想完成的事… Enter 发送，Shift + Enter 换行"></textarea><button type="button" class="icon-btn" data-open-modal="model-picker" title="模型设置">${icon('sliders',16)}</button><button class="primary search-submit" type="submit" aria-label="发送消息">${icon('arrowUp',18)}</button></div><div class="compose-foot"><span>${icon('shield',11)} 当前为本地演示，不会发送到真实 AI 服务</span><span>上下文窗口 · 16K</span></div><input id="fileInput" type="file" multiple hidden></form></section><aside class="panel"><div class="panel-head"><div><h3>智能入口</h3><p>选一个方向开始协作</p></div><span class="tag info">AI</span></div><div class="prompt-card" data-prompt="分析这个产品想法，输出目标用户、核心场景、MVP 功能、风险与验收指标。" data-send-prompt><span class="prompt-icon">${icon('brain',17)}</span><div><strong>需求分析</strong><p>从想法到结构化产品方案</p></div></div><div class="prompt-card" data-prompt="帮我把这份工作拆成阶段、依赖关系、负责人和验收标准。" data-send-prompt><span class="prompt-icon">${icon('workflow',17)}</span><div><strong>工作流规划</strong><p>任务拆解与执行路径</p></div></div><div class="prompt-card" data-prompt="请给我一份文档摘要，包含核心结论、风险、关键数据和待办。" data-send-prompt><span class="prompt-icon">${icon('fileText',17)}</span><div><strong>文档理解</strong><p>摘要、关键事实与行动项</p></div></div><div class="prompt-card" data-prompt="规划一个 Excel 分析工作流：数据清理、指标定义、可视化、结论与报告。" data-send-prompt><span class="prompt-icon">${icon('chart',17)}</span><div><strong>数据洞察</strong><p>把表格转为可行动的结论</p></div></div><div style="margin-top:20px;padding:13px;border:1px solid #dfe8f8;border-radius:14px;background:linear-gradient(135deg,#f1f7ff,#f6f0ff)"><div style="display:flex;gap:9px;align-items:center"><span class="tool-icon" style="width:32px;height:32px">${icon('shield',16)}</span><div><strong style="font-size:11px">你的内容由你掌控</strong><p class="tiny muted" style="margin:3px 0 0;line-height:1.6">正式版可接入模型服务、权限校验与私有文件处理。</p></div></div></div></aside></div></div>`}
function workspacePage(){return `<div class="page page-transition">${pageTitle('FILE INTELLIGENCE','文件处理工作台','一处完成上传、格式转换与文件整理。支持本地选择文件进行交互演示。',`<button class="secondary" data-open-modal="batch-settings">${icon('sliders',15)} 批处理设置</button>`)}<div class="workgrid"><section class="panel"><div class="panel-head"><div><h3>选择处理方式</h3><p>从常用任务开始，其他选项随时可调整。</p></div><span class="tag info">已接真实后端</span></div><div class="tabs"><button class="tab active" data-worktab="convert">格式转换</button><button class="tab" data-worktab="extract">信息提取</button><button class="tab" data-worktab="organize">文件整理</button><button class="tab" data-worktab="summarize">AI 总结</button></div><div style="margin-top:16px"><div class="dropzone" id="dropzone" role="button" tabindex="0"><div class="tool-icon" style="width:54px;height:54px;border-radius:17px;margin:0 auto 12px">${icon('upload',24)}</div><strong>将文件拖到这里，或浏览本地文件</strong><p>支持 PDF、DOCX、XLSX、CSV、TXT、PNG、JPG 等常见格式</p><div style="margin-top:13px"><button class="primary btn-sm" type="button" data-file-trigger>选择文件 ${icon('arrow',13)}</button></div></div><input id="fileInput" type="file" multiple hidden><div class="converter-options"><button class="option-card selected" data-output="Word"><strong>${icon('fileText',15)} PDF → Word</strong><span>可编辑文档</span></button><button class="option-card" data-output="Excel"><strong>${icon('chart',15)} PDF → Excel</strong><span>提取表格</span></button><button class="option-card" data-output="PDF"><strong>${icon('files',15)} 合并 PDF</strong><span>合并与排序</span></button><button class="option-card" data-output="摘要"><strong>${icon('sparkles',15)} AI 摘要</strong><span>提炼重点</span></button></div><div class="panel-head" style="margin-top:23px"><div><h3>处理队列</h3><p>点击「开始处理」后上传处理，结果自动下载</p></div><button class="ghost-btn btn-sm" data-toast="队列已刷新（演示）">${icon('refresh',13)} 刷新</button></div><div id="uploadedFiles"><div class="empty-state" style="padding:28px 12px"><span class="tool-icon" style="margin:auto">${icon('files',19)}</span><strong style="margin-top:10px">还没有添加文件</strong><p>添加一个文件，体验队列和状态交互。</p></div></div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:16px"><button class="secondary" data-toast="队列已清空（演示）" data-clear-files>清空队列</button><button class="primary" data-process-files>开始处理 ${icon('arrow',14)}</button></div></div></section><aside class="panel"><div class="panel-head"><div><h3>处理设置</h3><p>按当前任务调整输出偏好。</p></div>${icon('settings',17)}</div><div class="form-row"><label class="field-label">目标格式</label><select class="select" id="outputFormat"><option>Word (.docx)</option><option>Excel (.xlsx)</option><option>PDF (.pdf)</option><option>Markdown (.md)</option><option>JSON (.json)</option></select></div><div class="form-row"><label class="field-label">文件质量</label><div class="tabs" style="width:100%"><button class="tab active" data-quality="balanced">均衡</button><button class="tab" data-quality="high">高质量</button><button class="tab" data-quality="small">较小体积</button></div></div><div class="settings-row"><div><strong>识别文档结构</strong><p>尽量保留标题、表格和层级。</p></div><button class="switch on" role="switch" aria-checked="true"></button></div><div class="settings-row"><div><strong>生成处理摘要</strong><p>展示结果概览和需检查项。</p></div><button class="switch on" role="switch" aria-checked="true"></button></div><div class="settings-row"><div><strong>压缩输出文件</strong><p>尽可能降低最终文件体积。</p></div><button class="switch" role="switch" aria-checked="false"></button></div><div style="margin-top:18px;padding:13px;background:#f0f5ff;border:1px solid #dce7ff;border-radius:14px"><div style="display:flex;gap:8px;align-items:center;color:#4a67c6;font-size:11px;font-weight:700">${icon('shieldCheck',15)} 本地隐私提示</div><p class="tiny muted" style="line-height:1.65;margin:6px 0 0">文件在服务器内存中处理：用完即释放、不落盘；已支持 PDF→Word、PDF→Excel、合并/拆分/压缩 PDF</p></div></aside></div></div>`}
function analyticsPage(){return `<div class="page page-transition">${pageTitle('INSIGHT STUDIO','数据洞察中心','用更直观的图表理解趋势、发现异常，并把数据变成下一步行动。',`<button class="secondary" data-open-modal="date-range">${icon('calendar',14)} 最近 30 天</button><button class="primary" data-export-csv>${icon('download',14)} 导出摘要</button>`)}<div class="metric-grid">${metric('已分析记录','12,846','12.5%','database')}${metric('自动化任务','8,672','8.3%','workflow','mint')}${metric('平均处理效率','68.4%','5.1%','zap','violet')}${metric('节省时间','2.4h','16.8%','clock','peach')}</div><div class="section chart-layout"><section class="panel chart-card"><div class="chart-title"><div><h3>使用趋势与任务完成度</h3><p>按日查看平台内的任务处理走势</p></div><div class="tabs"><button class="tab active" data-chart-period="7">7 天</button><button class="tab" data-chart-period="30">30 天</button><button class="tab" data-chart-period="90">90 天</button></div></div>${lineChart('usage',true)}<div class="legend"><span><i></i>任务完成数</span><span><i class="purple"></i>活跃用户</span></div></section><section class="panel chart-card"><div class="chart-title"><div><h3>工具使用结构</h3><p>各工具类别占比</p></div><button class="icon-btn" data-open-modal="chart-details">${icon('more',15)}</button></div>${donut()}<div style="margin-top:10px"><a class="text-link" href="tools.html">探索工具详情 ${icon('arrow',13)}</a></div></section></div><div class="section split"><section class="table-card"><div class="table-toolbar"><div><h3>最近分析任务</h3><span class="tiny muted">演示数据 · 可搜索</span></div><input class="field" style="max-width:220px" data-table-search="analysisTable" placeholder="搜索任务名称…"></div><div class="table-wrap"><table id="analysisTable"><thead><tr><th>任务名称</th><th>类型</th><th>时间</th><th>状态</th><th>操作</th></tr></thead><tbody>${[['Q2 销售趋势分析','Excel','今天 14:32','已完成'],['用户反馈聚类','AI 分析','今天 13:50','已完成'],['产品需求摘要','文档','今天 11:08','已完成'],['API 错误日志整理','数据处理','昨天 18:24','处理中'],['市场报告洞察','AI 分析','昨天 16:03','已完成']].map((r,i)=>`<tr><td><strong style="color:#26395e">${r[0]}</strong></td><td>${r[1]}</td><td>${r[2]}</td><td><span class="status ${r[3]==='处理中'?'processing':''}">${r[3]}</span></td><td><button class="ghost-btn btn-sm" data-toast="已打开任务 ${r[0]}">查看</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h3>AI 洞察摘要</h3><p>基于示例数据生成</p></div><span class="tool-icon violet" style="width:32px;height:32px">${icon('sparkles',16)}</span></div><div class="prompt-card"><span class="prompt-icon">${icon('chart',16)}</span><div><strong>文档与数据任务持续增长</strong><p>近 7 日任务量较上一周期增长约 12%，建议优先优化高频格式转换流程。</p></div></div><div class="prompt-card"><span class="prompt-icon" style="background:#fff4e8;color:#bd823b">${icon('clock',16)}</span><div><strong>处理耗时仍有改善空间</strong><p>结构复杂的文档平均耗时偏高，可在实际服务端增加队列与异步通知。</p></div></div><button class="secondary" style="width:100%;margin-top:10px" data-open-modal="insight-detail">${icon('sparkles',14)} 生成完整分析报告</button></section></div></div>`}
function workflowsPage(){return `<div class="page page-transition">${pageTitle('AUTOMATION STUDIO','智能工作流','把 AI、文件和数据工具连接起来，让多步骤工作自动衔接。',`<button class="primary" data-open-modal="new-workflow">${icon('plus',15)} 创建工作流</button>`)}<div class="ai-banner" style="margin:0 0 22px"><div><div class="eyebrow" style="color:#637bdf">WORKFLOW BUILDER</div><h3>让流程替你跑起来，而不是记住每一步。</h3><p>从触发条件、输入数据到 AI 分析和输出结果，用可理解的方式管理每个节点。</p></div><div class="banner-right"><div class="banner-orb"></div></div></div><section class="panel"><div class="panel-head"><div><h3>我的工作流</h3><p>可复制、调整和继续配置的自动化蓝图。</p></div><div class="tabs"><button class="tab active" data-workflow-filter="all">全部</button><button class="tab" data-workflow-filter="active">运行中</button><button class="tab" data-workflow-filter="draft">草稿</button></div></div><div class="tool-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))">${workflowCard('每周业务简报','表格输入 → 趋势分析 → 生成简报','chart','运行中','active')}${workflowCard('需求澄清助手','提交想法 → 问题清单 → PRD 草案','brain','草稿','draft')}${workflowCard('文档归档工作流','上传文件 → 提取元信息 → 分类整理','files','运行中','active')}${workflowCard('API 日志检查','导入日志 → 异常聚类 → 生成摘要','terminal','草稿','draft')}${workflowCard('会议纪要助手','纪要整理 → 决议抽取 → 任务列表','message','运行中','active')}${workflowCard('月度数据报告','汇总指标 → 图表生成 → 报告导出','chartPie','已暂停','draft')}</div></section><section class="section panel"><div class="panel-head"><div><h3>工作流由这些步骤组成</h3><p>通过可组合的节点，让自动化透明且可理解。</p></div></div><div class="workflow">${[['触发','文件 / 定时','zap'],['整理输入','结构化上下文','files'],['AI 处理','分析 / 生成','brain'],['输出结果','报告 / 通知','check']].map((s,i)=>`<div class="workflow-step"><div class="step-icon">${icon(s[2],18)}</div><strong>${s[0]}</strong><small>${s[1]}</small></div>`).join('')}</div></section></div>`}
function workflowCard(title,desc,ic,status,filter){return `<article class="tool-card" data-workflow-state="${filter}"><div class="tool-card-top"><span class="tool-icon">${icon(ic,20)}</span><span class="status ${status==='运行中'?'':'idle'}">${status}</span></div><h3>${title}</h3><p>${desc}</p><div style="display:flex;gap:7px;margin-top:16px"><button class="secondary btn-sm" data-open-modal="workflow-detail" data-workflow-title="${title}">查看流程</button><button class="icon-btn" style="width:31px;height:31px" data-toast="已复制工作流草案">${icon('copy',13)}</button></div></article>`}
function profilePage(){return `<div class="page page-transition">${pageTitle('YOUR SPACE','个人中心','管理个人偏好、文件记录和工作方式，让每次回到 Nova 都能顺手继续。',`<button class="secondary" data-open-modal="preferences">${icon('settings',15)} 偏好设置</button>`)}<div class="split"><section class="panel"><div style="display:flex;align-items:center;gap:16px;padding-bottom:20px;border-bottom:1px solid #e9eef7"><div class="avatar" style="width:62px;height:62px;font-size:22px" id="pf-avatar">N</div><div style="flex:1"><h2 style="margin:0 0 4px;font-size:20px"id="pf-name">Nova 用户</h2><p class="muted small" style="margin:0"id="pf-mail">hello@nova.tools · 演示账户</p><div class="chips" style="margin-top:8px"><span class="tag info">${icon('sparkles',12)} Explorer 体验版</span><span class="tag good">状态正常</span></div></div><button class="secondary btn-sm" data-open-modal="edit-profile">编辑资料</button></div><div class="metric-grid" style="grid-template-columns:repeat(3,minmax(0,1fr));margin-top:17px">${metric('处理文件','128','18','files')}${metric('AI 会话','86','12','message','violet')}${metric('节省时间','12.6h','9.4','clock','mint')}</div><div class="section-head" style="margin-top:25px"><div><h2 style="font-size:15px">账户设置</h2><p>让工作空间适合你的习惯。</p></div></div>${settingsRow('个人资料','更新昵称、头像与联系邮箱','edit-profile')}${settingsRow('通知偏好','管理任务完成与系统通知','preferences')}${settingsRow('隐私与安全','了解本地演示数据和服务边界','privacy')}${settingsRow('语言和外观','切换界面语言与主题偏好','preferences')}</section><section class="panel"><div class="panel-head"><div><h3>已连接的工作空间</h3><p>第三方服务连接为演示状态。</p></div></div>${connectionRow('Google Drive','云端文件访问','globe')}${connectionRow('Microsoft 365','Word / Excel 文档','files')}${connectionRow('GitHub','开发项目与代码','code')}<button class="secondary" style="width:100%;margin-top:12px" data-open-modal="connect-service">${icon('plus',14)} 连接新服务</button><div class="ai-banner" style="margin-top:20px;padding:17px"><div><h3 style="font-size:14px">带上你的工作偏好</h3><p>在正式版本中，偏好可以用于定制 AI 输出格式与常用工作流。</p></div><span class="banner-orb" style="width:48px;height:48px"></span></div></section></div></div>`}
function settingsRow(title,desc,modal){return `<button class="settings-row" style="width:100%;text-align:left;border:0;background:transparent;cursor:pointer" data-open-modal="${modal}"><div><strong>${title}</strong><p>${desc}</p></div><span style="color:#90a0bc">${icon('chevron',15)}</span></button>`}
function connectionRow(title,desc,ic){return `<div class="recent-row"><span class="tool-icon" style="width:36px;height:36px">${icon(ic,17)}</span><div class="file-meta"><strong>${title}</strong><span>${desc}</span></div><span class="tag warm">未连接</span></div>`}
function mobilePage(){return `<div class="page page-transition">${pageTitle('NOVA ON THE GO','随时随地，灵感不断线','移动端沿用同一套工具、文件与 AI 会话；重要的是一致的体验，而不是缩小版的网站。',`<button class="primary" data-open-modal="app-preview">${icon('smartphone',15)} 体验移动端</button>`)}<div class="mobile-showcase">${phonePreview('首页','把复杂工作变得简单',0)}${phonePreview('工具','找到合适的下一步',1)}${phonePreview('数据洞察','让数据说明问题',2)}</div><section class="section ai-banner"><div><h3>一个账户，多端接续</h3><p>这里展示的是响应式移动界面原型；真正的跨设备同步需要连接用户账户与后端数据服务。</p></div><button class="secondary" data-open-modal="app-preview">查看体验说明 ${icon('arrow',14)}</button></section></div>`}
function phonePreview(title,subtitle,index){return `<div class="panel" style="padding:18px 14px;text-align:center"><div class="phone-frame"><div class="phone-screen"><div class="phone-notch"></div><div class="phone-brand"><span style="display:flex;align-items:center;gap:5px;color:#294eab">${icon('planet',14)} Nova</span>${icon('more',14)}</div><h3>${index===0?'让每一次工作\n都有 AI 在你身后':index===1?'工具，在手边': '数据更清晰'}</h3><p style="font-size:10px;color:#7787a5;text-align:left;line-height:1.6">${subtitle}</p><div class="searchbar" style="padding:6px 8px;margin-top:15px;gap:6px;border-radius:11px"><span>${icon('search',12)}</span><input placeholder="搜索工具…" style="font-size:9px"><span style="color:#536fe1">${icon('arrow',12)}</span></div><div class="phone-shortcuts">${[['fileText','文档'],['chart','数据'],['brain','AI 助手'],['image','图片'],['code','开发'],['workflow','更多']].map((v,i)=>`<a href="${['workspace.html','analytics.html','ai.html','workspace.html','tools.html','workflows.html'][i]}"><span class="tool-icon ${i===1?'mint':i===2?'violet':''}">${icon(v[0],15)}</span>${v[1]}</a>`).join('')}</div><div class="panel" style="padding:10px;margin-top:15px;text-align:left;background:#fff"><strong style="font-size:10px">最近使用</strong>${['产品需求草案.md','销售趋势.xlsx'].slice(0,index===0?2:1).map((x,i)=>`<div style="display:flex;gap:6px;align-items:center;font-size:8px;color:#74839e;padding:8px 0;border-bottom:1px solid #edf1f7">${icon('fileText',12)}${x}<span style="margin-left:auto">${i?'昨天':'2h'}</span></div>`).join('')}</div><div class="phone-bottom"><span>⌂ 首页</span><span>▦ 工具</span><span>◉ AI</span><span>◯ 我的</span></div></div></div><h3 style="font-size:13px;margin:15px 0 4px">${title}</h3><p class="muted tiny" style="margin:0">轻盈界面 · 单手可达</p></div>`}
function loginPage(){return `<main class="login-wrap"><section class="login-card">${logo()}<div class="tool-icon login-mark" style="margin-top:28px">${icon('sparkles',23)}</div><h1>欢迎回到 Nova</h1><p>把你的工作继续在这里。轻一点开始，清晰地完成。</p><form id="loginForm"><div class="form-row"><label class="field-label" for="email">用户名</label><input id="email" class="field" type="text" required placeholder="用户名"></div><div class="form-row"><label class="field-label" for="password">密码</label><input id="password" class="field" type="password" required placeholder="输入你的密码"></div><div style="display:flex;justify-content:space-between;align-items:center;margin:3px 0 18px"><label class="small muted"><input type="checkbox" checked> 保持登录</label><button type="button" class="ghost-btn btn-sm" data-open-modal="forgot-password">忘记密码？</button></div><button class="primary" style="width:100%;padding:13px" type="submit">进入工作空间 ${icon('arrow',15)}</button></form><div class="divider-label">第三方登录即将支持</div><div class="social-row"><button class="social-btn" data-toast="Google 登录为演示功能">◉ Google</button><button class="social-btn" data-toast="GitHub 登录为演示功能">${icon('code',15)} GitHub</button></div><p class="tiny muted" style="line-height:1.7;margin:21px 0 0">登录后即可使用文件处理、CSV 清洗等真实工具；会话仅保存在本机。<a href="help.html" style="color:#4d6ed8">了解隐私与安全</a></p></section></main>`}
function detailPage(){return `<div class="page page-transition">${pageTitle('TOOL DETAIL','PDF 转换中心','将 PDF 转换为可编辑的 Word、Excel 或图像；在上传前先选择合适的输出方式。',`<a class="secondary" href="tools.html">${icon('arrow',14)} 返回工具大全</a>`)}<div class="workgrid"><section class="panel"><div style="display:flex;gap:14px;align-items:center;padding-bottom:18px;border-bottom:1px solid #e9eef7"><span class="tool-icon peach" style="width:56px;height:56px;border-radius:18px">${icon('fileText',26)}</span><div style="flex:1"><h2 style="font-size:20px;margin:0 0 5px">PDF 转换中心</h2><p class="muted small" style="margin:0">文档处理 · 高精度 · 支持批量工作流</p></div><span class="tag good">推荐工具</span></div><div class="section-head" style="margin-top:22px"><div><h2 style="font-size:15px">选择转换任务</h2><p>选择一种输出格式开始。</p></div></div><div class="converter-options">${[['Word','可编辑文本','fileText'],['Excel','提取表格','chart'],['PPT','内容转幻灯片','files'],['图片','每页转图片','image']].map((x,i)=>`<button class="option-card ${i===0?'selected':''}" data-detail-format="${x[0]}"><span class="tool-icon ${i===1?'mint':i===2?'violet':'peach'}" style="width:35px;height:35px;margin-bottom:9px">${icon(x[2],17)}</span><strong>PDF → ${x[0]}</strong><span>${x[1]}</span></button>`).join('')}</div><div class="dropzone" style="margin-top:12px" id="detailDropzone"><span class="tool-icon" style="margin:0 auto 10px">${icon('upload',20)}</span><strong>上传要转换的 PDF 文件</strong><p>最大 100 MB · 服务器内存处理，用完即释放</p><button class="secondary btn-sm" style="margin-top:12px" data-file-trigger>选择文件</button><input type="file" id="fileInput" accept=".pdf" multiple hidden></div><div id="uploadedFiles"></div><div style="display:flex;justify-content:flex-end;margin-top:17px"><button class="primary" data-process-files>开始转换 ${icon('arrow',14)}</button></div></section><aside class="panel"><h3 style="margin:0 0 7px">转换能力</h3><p class="muted small" style="line-height:1.8;margin:0 0 15px">已接入真实处理引擎：状态实时更新，结果自动下载</p>${[['结构保留','尽量保留标题与排版','check'],['批量处理','一次提交多个文件','files'],['隐私保护','按服务端策略处理','shield'],['可追踪任务','提供进度与历史记录','clock']].map(x=>`<div class="recent-row"><span class="tool-icon" style="width:33px;height:33px">${icon(x[2],16)}</span><div class="file-meta"><strong>${x[0]}</strong><span>${x[1]}</span></div></div>`).join('')}<div class="ai-banner" style="padding:15px;margin-top:15px"><div><h3 style="font-size:13px">下一步：用 AI 总结</h3><p>转换后可直接提炼关键内容。</p><a href="ai.html" class="text-link" style="margin-top:9px">打开 AI 助手 ${icon('arrow',12)}</a></div></div></aside></div></div>`}
function helpPage(){return `<div class="page page-transition">${pageTitle('HELP & GUIDES','帮助与指南','快速找到合适的入口；复杂任务也可以从 AI 助手开始。',`<button class="primary" data-open-modal="contact-support">${icon('message',14)} 联系支持</button>`)}<div class="split"><section class="panel"><div class="searchbar" style="max-width:none"><span>${icon('search')}</span><input id="helpSearch" placeholder="搜索指南或常见问题…"></div><div class="section-head" style="margin-top:24px"><div><h2 style="font-size:16px">常见问题</h2><p>点击问题查看说明。</p></div></div><div id="faqList">${faqItem('Nova 可以处理哪些任务？','包括文档整理与格式转换、表格数据洞察、AI 需求分析、开发辅助和多步骤工作流。具体能力会因实际接入的模型与服务而有所不同。')}${faqItem('我的文件会被上传到哪里？','当前是静态演示版本，文件名与列表只保留在浏览器界面中，不会上传到后端。部署正式版前，需要明确文件处理服务的位置、保留时间和访问权限。')}${faqItem('AI 对话是真实模型吗？','当前 AI 回复为前端模拟，用来展示消息布局和工作流；真实回复需要接入模型 API、后端鉴权和限流策略。')}${faqItem('如何开始一个工作流？','进入智能工作流，选择现有模板，或新建一个目标描述。之后可以添加文件输入、AI 处理和结果输出节点。')}${faqItem('支持哪些文件格式？','原型展示 PDF、Word、Excel、CSV、Markdown、JSON 与常见图片格式；真正可处理的格式需根据后端能力启用。')}</div></section><aside class="panel"><div class="panel-head"><div><h3>从这里开始</h3><p>按当前需要选择一个入口。</p></div></div>${quickLink('打开 智能工作台','描述你希望完成的任务','brain','ai.html')}${quickLink('文件处理','上传和整理文件','files','workspace.html','mint')}${quickLink('工具大全','按场景找到工具','grid','tools.html','violet')}${quickLink('查看数据洞察','趋势与统计演示','chart','analytics.html','peach')}<div class="ai-banner" style="margin-top:15px;padding:16px"><div><h3 style="font-size:13px">还需要协助？</h3><p>告诉我们遇到的问题与期望结果。</p><button class="secondary btn-sm" style="margin-top:9px" data-open-modal="contact-support">提交问题</button></div></div></aside></div></div>`}
function faqItem(q,a){return `<details class="faq-item" data-search-item data-search-text="${esc(q+' '+a)}"><summary>${q}<span>${icon('plus',14)}</span></summary><p>${a}</p></details>`}
function requirementsPage(){return `<div class="page page-transition requirements-page">${pageTitle('NOVA PRODUCT INTELLIGENCE','AI 需求分析工作台','从模糊想法到清晰需求、用户画像、功能结构与可执行方案。',`<button class="secondary" data-open-modal="new-workflow">${icon('workflow',14)} 转为工作流</button><button class="secondary" data-toast="分析记录已加入历史（演示）">${icon('clock',14)} 历史记录</button>`)}<div class="req-steps"><div class="req-step active"><b>01</b><span><strong>需求输入</strong><small>描述目标与约束</small></span></div><i></i><div class="req-step active"><b>02</b><span><strong>智能分析</strong><small>拆解关键要素</small></span></div><i></i><div class="req-step"><b>03</b><span><strong>方案生成</strong><small>形成结构化文档</small></span></div><i></i><div class="req-step"><b>04</b><span><strong>文档导出</strong><small>继续协作</small></span></div></div><div class="req-layout"><section class="panel req-input-panel"><div class="panel-head"><div><h3>${icon('sparkles',17)} 输入你的需求描述</h3><p>描述问题即可，无需提前写好复杂提示词。</p></div><button class="ghost-btn btn-sm" data-fill-requirement>填入示例</button></div><form id="requirementsForm"><label class="field-label" for="requirementText">需求背景与目标</label><textarea class="textarea req-textarea" id="requirementText" required maxlength="3000" placeholder="例如：我希望为中小企业打造一个 AI 合同审核系统，支持多格式合同识别、风险条款提示、审阅报告生成，并能在团队中安全协作…"></textarea><div class="req-char-count"><span>描述越具体，方案越可用</span><span id="reqCharCount">0 / 3000</span></div><div class="form-row"><label class="field-label">分析模式</label><div class="req-mode-grid"><button type="button" class="req-mode active" data-req-mode="全面分析"><span>${icon('brain',17)}</span><strong>全面分析</strong><small>需求 · 用户 · 功能 · 风险</small></button><button type="button" class="req-mode" data-req-mode="快速梳理"><span>${icon('zap',17)}</span><strong>快速梳理</strong><small>优先得到清晰框架</small></button><button type="button" class="req-mode" data-req-mode="专业评审"><span>${icon('shieldCheck',17)}</span><strong>专业评审</strong><small>约束、风险与验收标准</small></button></div></div><div class="req-select-grid"><div><label class="field-label">行业类型</label><select class="select" id="reqIndustry"><option>企业服务 / SaaS</option><option>教育科技</option><option>电商零售</option><option>金融服务</option><option>医疗健康</option><option>其他行业</option></select></div><div><label class="field-label">目标用户</label><select class="select" id="reqUsers"><option>企业团队与管理员</option><option>个人消费者</option><option>开发者</option><option>运营与分析人员</option><option>多角色协作</option></select></div><div><label class="field-label">产品阶段</label><select class="select" id="reqStage"><option>MVP / 初步验证</option><option>产品规划</option><option>已有产品迭代</option><option>规模化增长</option></select></div><div><label class="field-label">交付深度</label><select class="select" id="reqDepth"><option>PRD + 用户流程</option><option>功能清单与优先级</option><option>技术方案与接口边界</option><option>完整评审包</option></select></div></div><div class="form-row"><label class="field-label">补充材料 <span class="muted">（可选）</span></label><label class="req-upload" for="reqFiles"><span class="req-upload-icon">${icon('upload',20)}</span><span><strong>拖放文件到这里，或点击选择</strong><small>支持 PDF、DOCX、XLSX、TXT；仅演示本地选取，不会上传服务器</small></span><span class="secondary btn-sm">选择文件</span><input id="reqFiles" type="file" multiple hidden></label><div id="reqFileNames" class="req-file-names"></div></div><div class="req-actions"><button type="submit" class="primary btn-lg" data-requirements-analyze>${icon('sparkles',16)} 开始智能分析 ${icon('arrow',15)}</button><button type="button" class="secondary btn-lg" data-clear-requirement>${icon('refresh',14)} 重置</button></div><p class="req-privacy">${icon('shieldCheck',12)} 本地演示模式 · 输入内容仅用于展示结果结构</p></form></section><section class="panel req-results-panel"><div class="req-result-head"><div><div class="eyebrow">AI GENERATED STRUCTURE</div><h3>分析结果预览</h3><p>结构化展示需求要点，便于评审、修改和导出。</p></div><span class="tag good"><i class="status-dot"></i> 示例结果</span></div><div class="req-tabs"><button class="active" data-req-tab="overview">需求概览</button><button data-req-tab="tree">需求结构</button><button data-req-tab="persona">用户画像</button><button data-req-tab="risks">风险分析</button></div><div class="req-result-body" id="reqResultBody"><div class="req-overview"><div class="req-result-card req-summary"><div class="req-card-title">${icon('target',15)} 需求概览 <span class="tag info">初步建议</span></div><h4 id="reqResultTitle">AI 合同审核与风险管理系统</h4><p id="reqResultSummary">面向企业法务与业务团队，建立从合同导入、条款识别、风险提示到审阅报告生成的智能工作流。</p></div><div class="req-mini-grid"><div class="req-result-card"><span class="req-mini-icon blue">${icon('users',16)}</span><small>目标用户</small><strong id="reqMetricUsers">法务 / 企业管理员</strong></div><div class="req-result-card"><span class="req-mini-icon violet">${icon('layers',16)}</span><small>核心模块</small><strong>6 个能力域</strong></div><div class="req-result-card"><span class="req-mini-icon mint">${icon('calendar',16)}</span><small>建议周期</small><strong>6–10 周</strong></div><div class="req-result-card"><span class="req-mini-icon peach">${icon('flag',16)}</span><small>优先策略</small><strong>先验证高频路径</strong></div></div><div class="req-result-card"><div class="req-card-title">${icon('workflow',15)} 推荐的核心流程</div><div class="req-flow"><span>合同导入</span><i>→</i><span>AI 识别</span><i>→</i><span>风险标注</span><i>→</i><span>报告导出</span></div></div><div class="req-result-card"><div class="req-card-title">${icon('listChecks',15)} MVP 功能清单</div><ul class="req-check-list"><li><span>${icon('check',13)}</span> 多格式合同上传与文本提取</li><li><span>${icon('check',13)}</span> 关键条款识别与风险等级标注</li><li><span>${icon('check',13)}</span> 生成可编辑的审阅摘要和报告</li><li><span>${icon('check',13)}</span> 团队权限、版本记录与操作审计</li></ul></div></div></div><div class="req-results-foot"><span>${icon('info',12)} AI 结果是结构样例，可继续编辑</span><div><button class="secondary btn-sm" data-copy-requirement>${icon('copy',12)} 复制摘要</button><button class="primary btn-sm" data-export-csv>${icon('download',12)} 导出数据</button></div></div></section></div></div>`}
function developerPage(){return `<div class="page page-transition developer-page">${pageTitle('NOVA DEVELOPER STUDIO','开发工具 · 代码实验室','在线格式化、校验和理解结构化数据；轻量快捷，专注解决问题。',`<button class="secondary" data-open-modal="model-picker">${icon('sliders',14)} 工具设置</button><button class="primary" data-toast="开发工作区已准备好（演示）">${icon('zap',14)} 快速运行</button>`)}<div class="dev-workbench"><aside class="dev-sidebar"><div class="dev-sidebar-head"><span class="tool-icon violet">${icon('code',17)}</span><div><strong>开发工具箱</strong><small>常用工具 · 代码效率</small></div></div>${[['JSON 格式化','braces'],['API 请求调试','terminal'],['SQL 格式化','database'],['正则表达式','scan'],['代码生成','sparkles'],['Base64 编码','key']].map((x,i)=>`<button class="dev-nav ${i===0?'active':''}" data-dev-tool="${x[0]}">${icon(x[1],15)} ${x[0]}</button>`).join('')}<div class="dev-sidebar-tip"><strong>${icon('shieldCheck',14)} 本地处理</strong><p>当前编辑器直接在浏览器内运行，不会自动发送代码到远端服务。</p></div></aside><section class="dev-editor-card"><div class="dev-toolbar"><div class="dev-tabs"><button class="active" data-editor-tab="json">JSON 格式化</button><button data-editor-tab="schema">JSON Schema</button><button data-editor-tab="diff">结构对比</button></div><div class="dev-toolbar-actions"><span class="tag info">JSON</span><button class="icon-btn" title="清空" data-dev-clear>${icon('trash',14)}</button></div></div><div class="dev-filebar"><span><i class="dev-file-dot"></i> sample-data.json</span><span id="devEditorStatus">未验证 · 0 错误</span></div><div class="dev-editor"><div class="dev-line-numbers" id="devLineNumbers">1<br>2<br>3<br>4<br>5<br>6<br>7<br>8<br>9<br>10</div><textarea id="developerEditor" spellcheck="false" autocapitalize="off" autocomplete="off">{
  "project": "Nova Workspace",
  "version": "1.0.0",
  "features": ["AI assistant", "file processing", "analytics"],
  "limits": { "maxFileSizeMB": 100, "dailyRuns": 50 },
  "enabled": true
}</textarea></div><div class="dev-editor-footer"><span>UTF-8 <b>·</b> JSON <b>·</b> <span id="devLineCount">8 行</span></span><span id="devBytes">183 B</span></div><div class="dev-actionbar"><button class="secondary" data-dev-clear>${icon('trash',13)} 清空</button><button class="secondary" data-copy-code>${icon('copy',13)} 复制</button><button class="secondary" data-validate-json>${icon('check',13)} 校验</button><button class="primary" data-format-json>${icon('sparkles',13)} 格式化代码</button></div></section><aside class="dev-results"><div class="dev-result-header"><h3>检查结果</h3><span class="tag good" id="devValidationTag">待校验</span></div><div class="dev-status-card"><span class="dev-status-icon">${icon('shieldCheck',19)}</span><div><strong id="devValidationTitle">准备就绪</strong><p id="devValidationText">输入或粘贴 JSON 后，可格式化并校验语法。</p></div></div><div class="dev-check-list"><div><span>${icon('fileText',14)} JSON 语法</span><b id="devSyntaxStatus">待检查</b></div><div><span>${icon('database',14)} 数据结构</span><b>可解析</b></div><div><span>${icon('shield',14)} 隐私状态</span><b class="good-text">本地运行</b></div></div><div class="dev-preview-card"><div class="panel-head"><div><h3>结构预览</h3><p>解析后的键和值</p></div><button class="ghost-btn btn-sm" data-refresh-preview>刷新</button></div><div class="dev-tree" id="devTree"><div class="dev-tree-row depth-0"><span class="tree-key">root</span><span class="tree-type">object</span><span class="tree-count">5 keys</span></div><div class="dev-tree-row depth-1"><span class="tree-key">project</span><span class="tree-type">string</span></div><div class="dev-tree-row depth-1"><span class="tree-key">version</span><span class="tree-type">string</span></div><div class="dev-tree-row depth-1"><span class="tree-key">features</span><span class="tree-type">array</span></div><div class="dev-tree-row depth-1"><span class="tree-key">limits</span><span class="tree-type">object</span></div><div class="dev-tree-row depth-1"><span class="tree-key">enabled</span><span class="tree-type">boolean</span></div></div></div><div class="dev-tip">${icon('sparkles',15)} <span><strong>Nova 提示</strong><small>格式化前建议保留一份原始内容，便于回滚对比。</small></span></div></aside></div></div>`}
