function adminContentPage(){return `${adminPageTitle('ADMIN / CONTENT','内容管理','维护首页内容、公告与帮助文案；让重要信息及时、稳定地呈现。',`<button class="primary" data-open-modal="new-content">${icon('plus',14)} 新建内容</button>`)}<div class="metric-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))">${metric('已发布内容','28','4 本周','fileText')}${metric('待审核','3','需要处理','clock','peach')}${metric('首页模块','8','2 已调整','grid','violet')}</div><section class="section table-card"><div class="table-toolbar"><div><h3>内容列表</h3><span class="tiny muted">首页模块、公告与帮助内容</span></div><input class="field" style="max-width:230px" data-table-search="contentTable" placeholder="搜索标题…"></div><div class="table-wrap"><table id="contentTable"><thead><tr><th>标题</th><th>类型</th><th>更新者</th><th>更新时间</th><th>状态</th><th>操作</th></tr></thead><tbody>${[['首页主视觉','首页模块','Admin','今天 11:25','已发布'],['新手使用指南','帮助文档','Editor','昨天 16:40','已发布'],['数据安全说明','公告','Admin','昨天 14:03','待审核'],['AI 工作流模板介绍','产品内容','Editor','04-11 10:22','已发布'],['移动端上线提示','公告','Admin','04-10 13:08','草稿']].map(r=>`<tr><td><strong style="color:#2d3d60">${r[0]}</strong></td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td><span class="status ${r[4]==='已发布'?'':r[4]==='草稿'?'idle':'processing'}">${r[4]}</span></td><td><button class="ghost-btn btn-sm" data-content-edit="${r[0]}">编辑</button></td></tr>`).join('')}</tbody></table></div></section>`}
function rolesPage(){return `${adminPageTitle('ADMIN / ACCESS CONTROL','角色与权限','按角色组织管理能力；生产环境必须在服务端再次校验每项操作。',`<button class="primary" data-open-modal="new-role">${icon('plus',14)} 新建角色</button>`)}<div class="tool-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))">${roleCard('超级管理员','拥有平台全部管理权限','SA',true,'系统配置、用户、工具、审计、导出')}${roleCard('运营管理员','管理工具、内容与数据报告','OP',false,'工具管理、内容发布、数据查看')}${roleCard('内容编辑','维护帮助和首页内容','ED',false,'内容管理、公告编辑、预览')}</div><section class="section panel"><div class="panel-head"><div><h3>权限矩阵</h3><p>勾选项只更新当前页面的演示状态。</p></div><button class="secondary btn-sm" data-save-settings>保存权限</button></div><div class="table-wrap"><table><thead><tr><th>权限范围</th><th>超级管理员</th><th>运营管理员</th><th>内容编辑</th></tr></thead><tbody>${[['查看运营数据',true,true,true],['管理用户',true,true,false],['启用与下架工具',true,true,false],['编辑首页内容',true,true,true],['修改系统配置',true,false,false],['查看审计日志',true,true,false],['发起数据导出',true,true,false]].map(r=>`<tr><td>${r[0]}</td>${r.slice(1).map(v=>`<td><input type="checkbox" ${v?'checked':''} data-permission aria-label="${r[0]} 权限"></td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}
function roleCard(title,sub,abbr,active,perms){return `<article class="tool-card"><div style="display:flex;align-items:center;justify-content:space-between"><span class="tool-icon ${abbr==='OP'?'mint':abbr==='ED'?'peach':''}">${icon('shieldCheck',20)}</span><span class="tag ${active?'info':''}">${abbr}</span></div><h3>${title}</h3><p>${sub}</p><div style="margin-top:11px;font-size:10px;color:#8b99b2">${perms}</div><button class="secondary btn-sm" style="margin-top:14px" data-open-modal="edit-role" data-role-title="${title}">查看权限 ${icon('arrow',12)}</button></article>`}
function logsPage(){return `${adminPageTitle('ADMIN / AUDIT TRAIL','系统日志','查看后台管理操作与服务事件的记录；生产日志需在服务端落库和脱敏。',`<button class="secondary" data-open-modal="log-filters">${icon('filter',14)} 筛选</button><button class="primary" data-export-csv>${icon('download',14)} 导出日志</button>`)}<div class="metric-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))">${metric('今天事件','18,462','8.2%','activity')}${metric('异常事件','12','3 待查看','shield','peach')}${metric('审计覆盖率','100%','稳定','check','mint')}</div><section class="section table-card"><div class="table-toolbar"><div><h3>事件流</h3><span class="tiny muted">示例日志 · 不代表真实运行环境</span></div><input class="field" style="max-width:250px" data-table-search="logsTable" placeholder="搜索事件或操作者…"></div><div class="table-wrap"><table id="logsTable"><thead><tr><th>时间</th><th>级别</th><th>事件</th><th>操作者</th><th>来源</th><th>详情</th></tr></thead><tbody>${[['22:14:32','INFO','工具列表更新','admin@nova.tools','Admin UI'],['22:13:58','INFO','用户状态调整','admin@nova.tools','User Admin'],['22:12:21','WARN','AI 服务延迟上升','system','AI Gateway'],['22:10:04','INFO','报告导出完成','editor@nova.tools','Analytics'],['22:08:47','INFO','新工作流模板创建','admin@nova.tools','Workflow'],['22:02:17','WARN','文件处理任务重试','system','Worker']].map(r=>`<tr><td>${r[0]}</td><td><span class="tag ${r[1]==='WARN'?'warm':'good'}">${r[1]}</span></td><td><strong style="color:#2d3d60">${r[2]}</strong></td><td>${r[3]}</td><td>${r[4]}</td><td><button class="ghost-btn btn-sm" data-log-detail="${r[2]}">查看详情</button></td></tr>`).join('')}</tbody></table></div></section>`}
function exportsPage(){return `${adminPageTitle('ADMIN / EXPORTS','数据导出','将筛选后的运营数据整理为 CSV 演示文件；生产版需做权限校验和异步导出。',`<button class="primary" data-open-modal="new-export">${icon('plus',14)} 新建导出任务</button>`)}<div class="metric-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))">${metric('本月导出','246','14.8%','download')}${metric('已完成','238','96.7%','check','mint')}${metric('处理中','3','队列正常','clock','peach')}</div><section class="section panel"><div class="panel-head"><div><h3>创建数据导出</h3><p>选择数据范围、时间周期和输出格式。</p></div><span class="tag info">CSV / JSON</span></div><form id="exportForm"><div class="tool-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))"><label class="option-card"><input type="checkbox" checked name="dataset" value="users"> <strong>用户数据</strong><span>账户、套餐与状态</span></label><label class="option-card"><input type="checkbox" checked name="dataset" value="tools"> <strong>工具使用</strong><span>调用量、完成率</span></label><label class="option-card"><input type="checkbox" name="dataset" value="events"> <strong>系统事件</strong><span>审计与操作记录</span></label></div><div class="toolbar" style="margin-top:17px"><div style="flex:1"><label class="field-label">开始日期</label><input class="field" type="date" value="2026-04-01"></div><div style="flex:1"><label class="field-label">结束日期</label><input class="field" type="date" value="2026-04-16"></div><div style="flex:1"><label class="field-label">输出格式</label><select class="select" id="exportFormat"><option>CSV</option><option>JSON</option></select></div></div><div style="display:flex;justify-content:flex-end"><button class="primary" type="submit">生成导出文件 ${icon('download',14)}</button></div></form></section><section class="section table-card"><div class="table-toolbar"><h3>最近导出任务</h3><span class="tiny muted">演示记录</span></div><div class="table-wrap"><table><thead><tr><th>任务编号</th><th>数据集</th><th>创建时间</th><th>状态</th><th>操作</th></tr></thead><tbody id="exportsTable"><tr><td class="mono">EXP-2026-0416-08</td><td>用户数据、工具使用</td><td>今天 13:20</td><td><span class="status">已完成</span></td><td><button class="ghost-btn btn-sm" data-export-csv>下载 CSV</button></td></tr><tr><td class="mono">EXP-2026-0415-21</td><td>系统事件</td><td>昨天 18:06</td><td><span class="status">已完成</span></td><td><button class="ghost-btn btn-sm" data-export-csv>下载 CSV</button></td></tr></tbody></table></div></section>`}
function notificationsPage(){return `${adminPageTitle('ADMIN / NOTIFICATIONS','通知中心','管理任务通知、产品公告和运营提醒的展示状态。',`<button class="primary" data-open-modal="new-notification">${icon('plus',14)} 创建通知</button>`)}<div class="metric-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))">${metric('已发送','42,816','12.8%','bell')}${metric('送达率','99.2%','0.3%','check','mint')}${metric('待发送','3','正常队列','clock','peach')}</div><section class="section panel"><div class="panel-head"><div><h3>通知模板</h3><p>开关只影响当前原型的显示状态。</p></div></div>${[['任务完成通知','文件处理或 AI 任务完成后通知用户','启用',true],['产品更新公告','新工具、功能和使用方式更新','启用',true],['安全提醒','登录、权限和敏感配置变化','启用',true],['周报摘要','每周发送个人工作概览','停用',false],['运营消息','促销或活动类消息','停用',false]].map(r=>`<div class="settings-row"><div><strong>${r[0]}</strong><p>${r[1]}</p><span class="tiny muted">渠道：站内通知 · 邮件（配置示意）</span></div><button class="switch ${r[3]?'on':''}" role="switch" aria-checked="${r[3]}"></button></div>`).join('')}</section><section class="section table-card"><div class="table-toolbar"><h3>最近通知</h3><button class="secondary btn-sm" data-toast="通知列表已刷新">${icon('refresh',12)} 刷新</button></div><div class="table-wrap"><table><thead><tr><th>标题</th><th>类型</th><th>受众</th><th>时间</th><th>状态</th></tr></thead><tbody>${[['Nova 工具更新','产品公告','全部用户','今天 09:15','已发送'],['文件处理任务已完成','任务通知','个人','昨天 16:48','已发送'],['系统维护窗口提醒','系统通知','管理员','昨天 10:02','已发送']].map(r=>`<tr>${r.map((c,i)=>`<td>${i===0?`<strong style="color:#2e3e61">${c}</strong>`:i===4?`<span class="status">${c}</span>`:c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}
function renderAdmin(){switch(document.body.dataset.adminPage||'index'){case'index':return adminDashboard();case'users':return usersPage();case'tools':return adminToolsPage();case'analytics':return adminAnalyticsPage();case'settings':return adminSettingsPage();case'content':return adminContentPage();case'roles':return rolesPage();case'logs':return logsPage();case'exports':return exportsPage();case'notifications':return notificationsPage();default:return adminDashboard()}}

/* Modal templates */
function modalConfig(name,trigger){const userName=trigger?.dataset.userName||trigger?.dataset.userDetail||'目标用户';const toolName=trigger?.dataset.toolEdit||'新工具';const workflowName=trigger?.dataset.workflowTitle||'新工作流';const roleName=trigger?.dataset.roleTitle||'运营管理员';const configs={
 'request-tool':{title:'提交一个工具需求',desc:'说说你现在的任务，以及你希望输出什么。',body:`<form data-demo-form data-success="工具需求已记录到演示队列"><div class="form-row"><label class="field-label">需求名称</label><input class="field" required placeholder="例如：自动整理合同中的关键条款"></div><div class="form-row"><label class="field-label">任务描述</label><textarea class="textarea" required placeholder="输入背景、文件类型、当前步骤与期望结果…"></textarea></div><div class="form-row"><label class="field-label">所属类别</label><select class="select"><option>AI 助手</option><option>文档处理</option><option>数据分析</option><option>开发工具</option></select></div><div class="modal-footer"><button type="button" class="secondary" data-close>取消</button><button class="primary">提交需求 ${icon('arrow',13)}</button></div></form>`},
 'new-workflow':{title:'创建智能工作流',desc:'先写清目标，节点与执行逻辑可以后续编辑。',body:`<form data-demo-form data-success="已创建工作流草案（演示）"><div class="form-row"><label class="field-label">工作流名称</label><input class="field" required placeholder="例如：每周产品数据简报"></div><div class="form-row"><label class="field-label">目标描述</label><textarea class="textarea" required placeholder="输入数据来自哪里、要经过哪些处理、最后输出什么…"></textarea></div><div class="form-row"><label class="field-label">模板</label><select class="select"><option>从空白开始</option><option>数据分析与报告</option><option>文档总结与归档</option><option>需求分析与规划</option></select></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">创建工作流 ${icon('arrow',13)}</button></div></form>`},
 'model-picker':{title:'智能工作台设置',desc:'选择本次会话的输出风格；当前仅用于交互演示。',body:`<form data-demo-form data-success="会话设置已更新（演示）"><div class="form-row"><label class="field-label">模型档位</label><div class="option-card selected"><strong>✨ Nova Smart</strong><span>综合推理、写作与任务拆解（演示）</span></div><div class="option-card" style="margin-top:8px"><strong>⚡ Nova Fast</strong><span>快速摘要与简单格式整理（演示）</span></div></div><div class="form-row"><label class="field-label">回复风格</label><select class="select"><option>清晰、结构化</option><option>简短直接</option><option>详细解释</option><option>创意探索</option></select></div><div class="form-row"><label class="field-label">上下文偏好</label><select class="select"><option>在本会话中保留上下文</option><option>每次任务单独处理</option></select></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">应用设置 ${icon('check',13)}</button></div></form>`},
 'date-range':{title:'选择分析周期',desc:'调整图表和指标显示的时间范围。',body:`<form data-demo-form data-success="时间范围已更新（演示）"><div class="form-row"><label class="field-label">快速范围</label><div class="tabs"><button type="button" class="tab active" data-preset-range="7">最近 7 天</button><button type="button" class="tab" data-preset-range="30">最近 30 天</button><button type="button" class="tab" data-preset-range="90">最近 90 天</button></div></div><div class="toolbar"><div style="flex:1"><label class="field-label">开始日期</label><input class="field" type="date" value="2026-03-17"></div><div style="flex:1"><label class="field-label">结束日期</label><input class="field" type="date" value="2026-04-16"></div></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">应用范围 ${icon('check',13)}</button></div></form>`},
 'add-user':{title:'添加用户',desc:'这里只创建本地演示条目，不会创建真实账号。',body:`<form data-demo-form data-success="用户已添加到演示列表"><div class="form-row"><label class="field-label">用户名称</label><input class="field" required placeholder="用户昵称"></div><div class="form-row"><label class="field-label">邮箱地址</label><input type="email" class="field" required placeholder="name@example.com"></div><div class="toolbar"><div style="flex:1"><label class="field-label">套餐</label><select class="select"><option>Free</option><option>Pro</option><option>Team</option></select></div><div style="flex:1"><label class="field-label">状态</label><select class="select"><option>正常</option><option>待验证</option><option>已暂停</option></select></div></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">添加用户 ${icon('plus',13)}</button></div></form>`},
 'add-tool':{title:'新增工具',desc:'创建新的工具目录条目。正式版需要后端审核和配置校验。',body:`<form data-demo-form data-success="工具条目已创建（演示）"><div class="form-row"><label class="field-label">工具名称</label><input class="field" required placeholder="例如：图片转 WebP"></div><div class="form-row"><label class="field-label">简短描述</label><input class="field" required placeholder="说明它帮助用户完成什么"></div><div class="toolbar"><div style="flex:1"><label class="field-label">分类</label><select class="select"><option>文档处理</option><option>数据分析</option><option>AI 助手</option><option>开发工具</option></select></div><div style="flex:1"><label class="field-label">状态</label><select class="select"><option>启用</option><option>草稿</option><option>待审核</option></select></div></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">创建工具 ${icon('plus',13)}</button></div></form>`},
 'preferences':{title:'偏好设置',desc:'为你调整工作台的默认体验。',body:`<form data-demo-form data-success="偏好设置已保存（演示）"><div class="form-row"><label class="field-label">界面主题</label><select class="select"><option>星云科技 · 深蓝与亮色</option><option>暖色晨光</option><option>纯净亮色</option></select></div>${settingsSwitch('减少动效','为偏好减少动画的用户降低运动强度',false)}${settingsSwitch('默认打开 智能工作台','进入网站后优先展示 AI 助手',false)}${settingsSwitch('显示最近文件','在首页展示最近使用的文件记录',true)}<div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">保存偏好 ${icon('check',13)}</button></div></form>`},
 'notifications':{title:'通知中心',desc:'这里展示当前原型的系统通知。',body:`<div class="recent-row"><span class="tool-icon mint">${icon('check',16)}</span><div class="file-meta"><strong>文件处理演示本地运行</strong><span>刚刚 · 所有本地交互正常</span></div><span class="tag good">系统</span></div><div class="recent-row"><span class="tool-icon violet">${icon('sparkles',16)}</span><div class="file-meta"><strong>Nova 智能工作台更新</strong><span>今天 · 新增工作流快捷入口</span></div><span class="tag info">产品</span></div><div class="recent-row"><span class="tool-icon peach">${icon('shield',16)}</span><div class="file-meta"><strong>隐私与服务说明</strong><span>提醒 · 当前为静态前端演示</span></div><span class="tag warm">提醒</span></div><div class="modal-footer"><button class="primary" data-close>我知道了</button></div>`},
 'edit-profile':{title:'编辑个人资料',desc:'更新本地界面展示的信息。',body:`<form data-demo-form data-success="个人资料已更新（演示）"><div class="form-row"><label class="field-label">显示名称</label><input class="field" value="Nova 用户"></div><div class="form-row"><label class="field-label">联系邮箱</label><input class="field" type="email" value="hello@nova.tools"></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">保存更改</button></div></form>`},
 'privacy':{title:'隐私与安全说明',desc:'当前原型的数据边界。',body:`<div class="prompt-card"><span class="prompt-icon">${icon('shield',16)}</span><div><strong>本地演示模式</strong><p>输入内容仅用于浏览器中交互展示，不会发往真实模型服务或业务 API。</p></div></div><div class="prompt-card"><span class="prompt-icon">${icon('lock',16)}</span><div><strong>正式版部署建议</strong><p>使用 HTTPS、服务端权限校验、密钥保管、请求限流、文件隔离与审计日志。</p></div></div><div class="modal-footer"><button class="primary" data-close>关闭</button></div>`},
 'connect-service':{title:'连接工作空间',desc:'当前外部服务连接为交互示例。',body:`<div class="tool-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${[['Google Drive','globe'],['Microsoft 365','files'],['GitHub','code'],['Notion','book']].map(x=>`<button class="option-card" data-toast="${x[0]} 连接流程为演示"><span class="tool-icon">${icon(x[1],18)}</span><strong>${x[0]}</strong><span>连接服务</span></button>`).join('')}</div><div class="modal-footer"><button class="secondary" data-close>取消</button></div>`},
 'app-preview':{title:'移动端体验说明',desc:'当前静态原型已经使用响应式布局模拟移动端界面。',body:`<div class="prompt-card"><span class="prompt-icon">${icon('smartphone',16)}</span><div><strong>移动端与桌面端共享视觉体系</strong><p>在窄屏下，导航切换为抽屉、工具卡片自动换列、对话输入区保持固定结构。</p></div></div><div class="prompt-card"><span class="prompt-icon">${icon('globe',16)}</span><div><strong>上线前仍需补齐</strong><p>账号同步、真实数据 API、上传与处理服务、离线策略和移动端性能测试。</p></div></div><div class="modal-footer"><button class="primary" data-close>完成</button></div>`},
 'forgot-password':{title:'重置密码',desc:'演示版不发送邮件。',body:`<form data-demo-form data-success="重置链接发送流程已演示"><div class="form-row"><label class="field-label">注册邮箱</label><input type="email" class="field" required placeholder="name@example.com"></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">发送重置链接</button></div></form>`},
 'contact-support':{title:'联系支持',desc:'请描述你遇到的问题，我们会将它整理为一个支持请求示例。',body:`<form data-demo-form data-success="支持请求已创建（演示）"><div class="form-row"><label class="field-label">问题类型</label><select class="select"><option>使用问题</option><option>文件处理</option><option>AI 功能建议</option><option>账户与安全</option></select></div><div class="form-row"><label class="field-label">问题描述</label><textarea class="textarea" required placeholder="说明你正在做什么、遇到了什么、期望如何工作…"></textarea></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">提交请求 ${icon('arrow',13)}</button></div></form>`},
 'batch-settings':{title:'批处理设置',desc:'设置所有排队文件的默认行为。',body:`<form data-demo-form data-success="批处理设置已保存（演示）"><div class="form-row"><label class="field-label">输出格式</label><select class="select"><option>与所选任务匹配</option><option>Word (.docx)</option><option>PDF (.pdf)</option><option>Excel (.xlsx)</option></select></div>${settingsSwitch('遇到失败时继续','单个文件失败时继续处理其他文件',true)}${settingsSwitch('完成后生成摘要','输出文件处理结果与状态汇总',true)}<div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">应用设置</button></div></form>`},
 'filters':{title:'筛选工具',desc:'组合多个条件快速缩小工具范围。',body:`<form data-demo-form data-success="工具筛选已应用（演示）"><div class="form-row"><label class="field-label">使用场景</label><select class="select"><option>全部场景</option><option>办公文档</option><option>数据分析</option><option>开发与 API</option></select></div><div class="form-row"><label class="field-label">工具类型</label><div class="chips"><label class="chip"><input type="checkbox" checked> AI 助手</label><label class="chip"><input type="checkbox" checked> 文档</label><label class="chip"><input type="checkbox"> 数据</label><label class="chip"><input type="checkbox"> 开发</label></div></div><div class="form-row"><label class="field-label">排序方式</label><select class="select"><option>推荐优先</option><option>使用频率</option><option>最近更新</option><option>名称 A-Z</option></select></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">应用筛选</button></div></form>`},
 'insight-detail':{title:'AI 洞察报告',desc:'由当前静态演示指标整理出的结构化摘要。',body:`<div class="prompt-card"><span class="prompt-icon">${icon('chart',16)}</span><div><strong>观察到的趋势</strong><p>示例指标显示文档处理和数据分析是高频场景，建议优先优化文件上传反馈和分析结果的可复用性。</p></div></div><div class="prompt-card"><span class="prompt-icon">${icon('workflow',16)}</span><div><strong>建议的下一步</strong><p>1. 对高频工具加入最近使用记录；2. 在耗时较长的任务中展示明确进度；3. 让 AI 摘要可以转成工作流。</p></div></div><div class="modal-footer"><button class="secondary" data-close>关闭</button><button class="primary" data-export-csv>导出摘要 ${icon('download',13)}</button></div>`},
 'chart-details':{title:'工具结构详情',desc:'类别分布用于展示如何将多维数据表达为清晰图表。',body:`${donut()}<p class="small muted" style="line-height:1.8">图中数值为演示数据，正式版需按实际工具调用事件聚合生成。</p><div class="modal-footer"><button class="primary" data-close>完成</button></div>`},
 'new-content':{title:'新建内容',desc:'创建首页展示模块、帮助文档或系统公告。',body:`<form data-demo-form data-success="内容草稿已创建（演示）"><div class="form-row"><label class="field-label">内容标题</label><input class="field" required placeholder="输入标题"></div><div class="form-row"><label class="field-label">内容类型</label><select class="select"><option>首页模块</option><option>公告</option><option>帮助文档</option></select></div><div class="form-row"><label class="field-label">正文内容</label><textarea class="textarea" required placeholder="编写内容…"></textarea></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">保存草稿</button></div></form>`},
 'new-role':{title:'新建角色',desc:'配置新的管理角色和初始权限。',body:`<form data-demo-form data-success="角色草案已创建（演示）"><div class="form-row"><label class="field-label">角色名称</label><input class="field" required placeholder="例如：数据分析员"></div><div class="form-row"><label class="field-label">描述</label><textarea class="textarea" placeholder="这个角色可以做什么？"></textarea></div><div class="form-row"><label class="field-label">初始权限</label><div class="chips"><label class="chip"><input type="checkbox" checked> 查看数据</label><label class="chip"><input type="checkbox"> 管理工具</label><label class="chip"><input type="checkbox"> 导出数据</label></div></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">创建角色</button></div></form>`},
 'edit-role':{title:`编辑角色：${roleName}`,desc:'查看并调整角色描述和操作权限。',body:`<form data-demo-form data-success="角色权限已更新（演示）"><div class="form-row"><label class="field-label">角色名称</label><input class="field" value="${esc(roleName)}" required></div>${settingsSwitch('允许查看运营数据','查看指标和图表',true)}${settingsSwitch('允许编辑工具目录','编辑工具名称、描述和状态',true)}${settingsSwitch('允许导出数据','下载演示 CSV',false)}<div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">保存角色</button></div></form>`},
 'log-filters':{title:'筛选系统日志',desc:'按事件级别和时间范围筛选日志。',body:`<form data-demo-form data-success="日志筛选已应用（演示）"><div class="form-row"><label class="field-label">事件级别</label><select class="select"><option>全部级别</option><option>INFO</option><option>WARN</option><option>ERROR</option></select></div><div class="form-row"><label class="field-label">事件来源</label><select class="select"><option>全部来源</option><option>Admin UI</option><option>AI Gateway</option><option>Worker</option></select></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">应用筛选</button></div></form>`},
 'new-export':{title:'新建导出任务',desc:'将筛选后的数据生成可下载的演示 CSV。',body:`<form data-demo-form data-success="导出任务已创建（演示）"><div class="form-row"><label class="field-label">数据类型</label><select class="select"><option>运营摘要</option><option>用户列表</option><option>工具调用日志</option></select></div><div class="form-row"><label class="field-label">输出格式</label><select class="select"><option>CSV</option><option>JSON</option></select></div><div class="form-row"><label class="field-label">备注（可选）</label><input class="field" placeholder="例如：4 月运营周报"></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">创建任务</button></div></form>`},
 'new-notification':{title:'创建通知',desc:'新通知只保存在本地演示状态中。',body:`<form data-demo-form data-success="通知草稿已保存（演示）"><div class="form-row"><label class="field-label">通知标题</label><input class="field" required placeholder="输入简短标题"></div><div class="form-row"><label class="field-label">通知内容</label><textarea class="textarea" required placeholder="输入通知说明…"></textarea></div><div class="form-row"><label class="field-label">受众</label><select class="select"><option>全部用户</option><option>管理员</option><option>Pro 用户</option></select></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">保存通知</button></div></form>`},
 'user-actions':{title:`用户操作：${userName}`,desc:'演示菜单；生产环境中每项操作都需要权限校验与审计。',body:`<div class="prompt-card"><span class="prompt-icon">${icon('user',16)}</span><div><strong>${userName}</strong><p>可以查看详情、调整状态或发起通知。</p></div></div><div class="tool-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))"><button class="option-card" data-toast="用户详情已打开（演示）">${icon('eye',17)}<strong>查看详情</strong><span>账户与使用情况</span></button><button class="option-card" data-toast="编辑用户操作已触发（演示）">${icon('pencil',17)}<strong>编辑资料</strong><span>更新用户信息</span></button><button class="option-card" data-toast="重置凭证流程为演示">${icon('key',17)}<strong>重置凭证</strong><span>需后端验证</span></button><button class="option-card" data-toast="状态调整已记录到演示提示">${icon('shield',17)}<strong>调整状态</strong><span>启用或暂停账户</span></button></div><div class="modal-footer"><button class="secondary" data-close>关闭</button></div>`},
 'tool-category':{title:'工具分类管理',desc:'分类会影响前台工具浏览与筛选。',body:`<form data-demo-form data-success="工具分类偏好已保存（演示）"><div class="form-row"><label class="field-label">分类显示方式</label><select class="select"><option>按工作场景</option><option>按文件类型</option><option>按热门程度</option></select></div><div class="form-row"><label class="field-label">首页展示分类</label><div class="chips"><label class="chip"><input type="checkbox" checked> 文档处理</label><label class="chip"><input type="checkbox" checked> AI 助手</label><label class="chip"><input type="checkbox" checked> 数据分析</label><label class="chip"><input type="checkbox"> 开发工具</label></div></div><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary">保存分类</button></div></form>`},
 'workflow-detail':{title:`工作流：${workflowName}`,desc:'查看流程节点并创建一个本地副本。',body:`<div class="workflow">${[['触发','输入数据','upload'],['解析','理解内容','fileSearch'],['AI 处理','生成结果','brain'],['输出','报告文件','download']].map(s=>`<div class="workflow-step"><div class="step-icon">${icon(s[2],17)}</div><strong>${s[0]}</strong><small>${s[1]}</small></div>`).join('')}</div><div class="prompt-card"><span class="prompt-icon">${icon('info',16)}</span><div><strong>流程说明</strong><p>节点顺序、输入输出与权限需在真实工作流引擎中进行校验；此处只展示交互样式。</p></div></div><div class="modal-footer"><button class="secondary" data-close>关闭</button><button class="primary" data-toast="已创建工作流副本（演示）">复制工作流 ${icon('copy',13)}</button></div>`},
 'tool-edit':{title:`编辑工具：${toolName}`,desc:'编辑名称、描述和状态。',body:`<form data-demo-form data-success="工具配置已更新（演示）"><div class="form-row"><label class="field-label">工具名称</label><input class="field" value="${esc(toolName)}"></div><div class="form-row"><label class="field-label">说明</label><textarea class="textarea">帮助用户更快完成任务。</textarea></div>${settingsSwitch('启用工具','让前台用户可以使用',true)}${settingsSwitch('首页推荐','在首页常用工具模块展示',true)}<div class="modal-footer"><button type="button" class="secondary" data-close>取消</button><button class="primary">保存</button></div></form>`}
};return configs[name]||{title:'Nova',desc:'当前为静态交互演示。',body:`<p class="small muted">此操作将在接入真实后端后完成。</p><div class="modal-footer"><button class="primary" data-close>知道了</button></div>`}}
function showModal(name,trigger){
  const c=modalConfig(name,trigger);
  let overlay=$('#globalModal');
  if(!overlay){overlay=document.createElement('div');overlay.id='globalModal';overlay.className='modal-backdrop';document.body.appendChild(overlay)}
  if(!overlay.dataset.bound){overlay.addEventListener('click',e=>{if(e.target===overlay)closeModal(overlay)});overlay.dataset.bound='true'}
  overlay.innerHTML=`<section class="modal modal-${esc(name)} ${name==='filters'||name==='workflow-detail'?'wide':''}" data-modal-kind="${esc(name)}" role="dialog" aria-modal="true" aria-labelledby="globalModalTitle"><div class="modal-head"><div><h2 id="globalModalTitle">${c.title}</h2><p>${c.desc||''}</p></div><button class="modal-close" data-close aria-label="关闭对话框">${icon('close',16)}</button></div><div class="modal-content">${c.body||''}</div></section>`;
  requestAnimationFrame(()=>overlay.classList.add('open'));
  document.body.style.overflow='hidden';
  overlay.querySelector('input:not([type=checkbox]),textarea,select')?.focus();
}
function closeModal(overlay){if(!overlay)return;overlay.classList.remove('open');document.body.style.overflow='';setTimeout(()=>{if(overlay.id==='globalModal')overlay.innerHTML=''},220)}
function toast(message='操作已完成',kind='success'){let stack=$('.toast-stack');if(!stack){stack=document.createElement('div');stack.className='toast-stack';document.body.appendChild(stack)}const el=document.createElement('div');el.className='toast';el.innerHTML=`<span class="toast-icon">${icon(kind==='error'?'close':'check',14)}</span><span>${esc(message)}</span>`;stack.appendChild(el);setTimeout(()=>{el.style.opacity='0';el.style.transform='translateY(8px)';setTimeout(()=>el.remove(),220)},3000)}
function commandPalette(){let overlay=$('#commandPalette');if(!overlay){overlay=document.createElement('div');overlay.id='commandPalette';overlay.className='modal-backdrop';overlay.innerHTML=`<section class="modal command-modal" role="dialog" aria-modal="true" aria-label="快速搜索"><div class="command-search">${icon('search',18)}<input id="commandInput" placeholder="搜索页面、工具或操作…"><span class="kbd">ESC</span></div><div class="command-items" id="commandItems"></div><div class="command-footer"><span>↑↓ 选择</span><span>Enter 打开</span><span>Esc 关闭</span><span style="margin-left:auto">Nova Quick Switch</span></div></section>`;document.body.appendChild(overlay);overlay.addEventListener('click',e=>{if(e.target===overlay)closeModal(overlay)});$('#commandInput',overlay).addEventListener('input',renderCommandItems);$('#commandInput',overlay).addEventListener('keydown',e=>{let items=$$('.command-item',overlay);let i=items.findIndex(x=>x.classList.contains('active'));if(e.key==='ArrowDown'){e.preventDefault();items.forEach(x=>x.classList.remove('active'));items[(i+1+items.length)%items.length]?.classList.add('active')}if(e.key==='ArrowUp'){e.preventDefault();items.forEach(x=>x.classList.remove('active'));items[(i-1+items.length)%items.length]?.classList.add('active')}if(e.key==='Enter'){e.preventDefault();items.find(x=>x.classList.contains('active'))?.click()}})}renderCommandItems();requestAnimationFrame(()=>overlay.classList.add('open'));document.body.style.overflow='hidden';setTimeout(()=>$('#commandInput',overlay)?.focus(),50)}
function renderCommandItems(){const root=$('#commandItems');if(!root)return;const input=$('#commandInput');const q=(input?.value||'').toLowerCase().trim();const all=[...routes,...adminRoutes].filter(r=>(r.label+' '+r.desc).toLowerCase().includes(q));root.innerHTML=all.map((r,i)=>`<a class="command-item ${i===0?'active':''}" href="${href(r.href)}"><span class="tool-icon">${icon(r.icon,17)}</span><span><strong>${r.label}</strong><small>${r.desc}</small></span><kbd class="kbd">↵</kbd></a>`).join('')||'<div class="empty-search">没有找到匹配的页面或工具。</div>';$$('.command-item',root).forEach(a=>a.addEventListener('click',()=>{closeModal($('#commandPalette'))}))}
function exportCSV(){const rows=[['日期','工具','调用量','完成率'],['2026-04-16','PDF 转 Word','12836','98.8%'],['2026-04-16','Excel 数据洞察','8421','97.9%'],['2026-04-16','AI 需求分析','15672','99.1%']];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='nova-demo-report.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('演示 CSV 已生成并下载')}
function processFileList(files){const list=$('#uploadedFiles');if(!list)return;window.__novaFiles=[...(window.__novaFiles||[]),...files];const empty=$('.empty-state',list);empty?.remove();[...files].forEach(f=>{const ext=(f.name.split('.').pop()||'FILE').toUpperCase().slice(0,5);const type=/pdf/i.test(ext)?'pdf':/xls|csv/i.test(ext)?'xls':/png|jpg|webp/i.test(ext)?'img':'';const row=document.createElement('div');row.className='recent-row';row.dataset.localFile=f.name;row.innerHTML=`<div class="file-icon ${type}">${esc(ext)}</div><div class="file-meta"><strong>${esc(f.name)}</strong><span>${(f.size/1024).toFixed(1)} KB · 已添加到本地工作区</span></div><span class="status">就绪</span><button class="icon-btn" style="width:30px;height:30px" data-remove-file aria-label="移除文件">${icon('close',13)}</button>`;list.prepend(row)});toast(`已添加 ${files.length} 个文件，点击「开始处理」上传`)}
function simulateAI(value){const messages=$('#chatMessages');if(!messages)return;const user=document.createElement('div');user.className='message user';user.innerHTML=`<div class="bubble-avatar">N</div><div class="bubble"></div>`;$('.bubble',user).textContent=value;messages.appendChild(user);const answer=document.createElement('div');answer.className='message';answer.innerHTML=`<div class="bubble-avatar">N</div><div class="bubble"><span class="muted">正在梳理目标、上下文和可执行步骤…</span><div class="thinking-dots" style="display:flex;gap:5px;margin-top:8px"><i class="mini-pulse"></i><i class="mini-pulse"></i><i class="mini-pulse"></i></div></div>`;messages.appendChild(answer);messages.scrollTop=messages.scrollHeight;setTimeout(()=>{const b=$('.bubble',answer);b.innerHTML=`<h4>我建议先这样推进</h4><p>我把你的输入整理为一份可执行的初步方案。以下为前端演示回复，真实模型尚未接入。</p><div class="prompt-card" style="margin:10px 0"><span class="prompt-icon">${icon('target',16)}</span><div><strong>目标与成功标准</strong><p>明确预期产出、目标对象以及如何判断任务已经完成。</p></div></div><ol style="padding-left:18px;margin:8px 0"><li style="padding:4px 0">整理现有材料与约束条件。</li><li style="padding:4px 0">拆分任务阶段，并定义每步输出。</li><li style="padding:4px 0">检查遗漏、风险和需确认的信息。</li></ol><p>接下来可以补充输出格式、目标用户或截止时间，我会继续细化。</p><div class="bubble-actions"><button class="soft-btn btn-sm" data-copy-text="目标澄清：明确产出和成功标准；信息整理：汇总材料与约束；执行路径：拆分阶段、输出和检查项。">${icon('copy',13)} 复制摘要</button><button class="secondary btn-sm" data-open-modal="new-workflow">${icon('workflow',13)} 转为工作流</button><button class="ghost-btn btn-sm" data-toast="已记录为收藏项（演示）">${icon('star',13)} 收藏</button></div>`;messages.scrollTop=messages.scrollHeight},750)}
function routeToAI(prompt){const target=href('ai.html');if(sessionSet('novaPrompt',prompt)){location.href=target}else{location.href=target+'?prompt='+encodeURIComponent(prompt)}}
function init(){
  if(!ROOT)return;
  if(IS_ADMIN){
    ROOT.innerHTML=adminShell(renderAdmin());
  }else if(PAGE==='login'){
    ROOT.innerHTML=renderFrontend();
  }else{
    ROOT.innerHTML=frontHeader()+renderFrontend()+`<footer class="page-footer"><span>${logo()} <span style="margin-left:12px">AI 让工作更简单 · 让创造更自由</span></span><div class="footer-links"><a href="help.html">帮助中心</a><a href="mobile.html">移动端</a><a href="admin/index.html">管理后台</a><span>静态交互原型 · 演示数据</span></div></footer>`;
  }
  document.body.classList.toggle('is-admin',IS_ADMIN);
  $$('a[href]').forEach(a=>{
    const raw=a.getAttribute('href');
    if(IS_ADMIN&&raw&&!raw.startsWith('../')&&!raw.startsWith('#')&&!/^https?:/.test(raw)&&!raw.startsWith('mailto:')&&!raw.startsWith('javascript:')){
      if(raw.startsWith('admin/'))a.setAttribute('href',raw.slice(6));
      else if(!['index.html','users.html','tools.html','analytics.html','settings.html','content.html','roles.html','logs.html','exports.html','notifications.html'].includes(raw))a.setAttribute('href','../'+raw);
    }
  });
  attachEvents();
  const saved=sessionGet('novaPrompt')||new URLSearchParams(location.search).get('prompt');
  if(PAGE==='ai'&&saved){sessionRemove('novaPrompt');const i=$('#aiInput');if(i){i.value=saved;setTimeout(()=>$('#aiForm')?.requestSubmit(),120)}}
  if(PAGE==='tools'){
    const params=new URLSearchParams(location.search);
    if(params.has('q')){const s=$('#toolSearch');if(s){s.value=params.get('q');s.dispatchEvent(new Event('input'))}}
  }
  if(PAGE==='developer'){updateDevMetrics();updateDevTree()}
}
function updateDevMetrics(){const v=$('#developerEditor')?.value||'';const lines=v.split('\n').length;if($('#devLineCount'))$('#devLineCount').textContent=`${lines} 行`;if($('#devBytes'))$('#devBytes').textContent=new Blob([v]).size+' B';if($('#devLineNumbers'))$('#devLineNumbers').innerHTML=Array.from({length:Math.max(1,lines)},(_,i)=>i+1).join('<br>')}
function updateDevTree(value){try{value=value??JSON.parse($('#developerEditor')?.value||'{}')}catch{return}const tree=$('#devTree');if(!tree)return;const rows=[];function walk(v,key,depth){const type=Array.isArray(v)?'array':v===null?'null':typeof v;if(depth>2)return;const detail=type==='object'?(Array.isArray(v)?`${v.length} items`:`${Object.keys(v||{}).length} keys`):String(v).slice(0,38);rows.push(`<div class="dev-tree-row depth-${Math.min(depth,2)}"><span class="tree-key">${esc(key)}</span><span class="tree-type">${type}</span><span class="tree-count">${esc(detail)}</span></div>`);if(depth<2&&v&&typeof v==='object')Object.entries(v).slice(0,8).forEach(([k,val])=>walk(val,k,depth+1))}walk(value,'root',0);tree.innerHTML=rows.slice(0,20).join('')}
