/* ===== REAL PIPELINE v1：工作台/详情页接真后端 + 登录真实化（捕获期拦截，不依赖演示处理器） ===== */
(function(){
  const EP={'detail-Word':'/api/fx/pdf-to-docx','detail-Excel':'/api/fx/pdf-to-xlsx','work-Word':'/api/fx/pdf-to-docx','work-Excel':'/api/fx/pdf-to-xlsx','work-PDF':'/api/fx/pdf-merge'};
  const FB={'/api/fx/pdf-to-docx':'converted.docx','/api/fx/pdf-to-xlsx':'converted.xlsx','/api/fx/pdf-merge':'merged.pdf'};
  function stat(n,t){const row=[...document.querySelectorAll('#uploadedFiles [data-local-file]')].find(r=>r.dataset.localFile===n);const s=row&&row.querySelector('.status');if(s)s.textContent=t}
  function dl(b,name){const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),4000)}
  function outName(cd,fb){if(cd){const m1=/filename\*=utf-8''([^;]+)/i.exec(cd);if(m1){try{return decodeURIComponent(m1[1])}catch(e){}}const m2=/filename="?([^";]+)"?/i.exec(cd);if(m2)return m2[1]}return fb}
  async function runOne(fd,ep,fb,label){
    const res=await fetch(ep,{method:'POST',body:fd});
    if(res.status===401){toast('请先登录后再处理文件');setTimeout(()=>location.href='login.html',600);return false}
    if(!res.ok){let m='处理失败';try{const j=await res.json();m=j.error||m}catch(e){};toast(label+'：'+m);return false}
    dl(await res.blob(),outName(res.headers.get('Content-Disposition'),fb));return true;
  }
  document.addEventListener('click',e=>{
    const rm=e.target.closest('[data-remove-file]');
    if(rm){const row=rm.closest('[data-local-file]');const n=row&&row.dataset.localFile;
      if(n&&window.__novaFiles){const i=window.__novaFiles.findIndex(f=>f.name===n);if(i>-1)window.__novaFiles.splice(i,1)}return}
    const btn=e.target.closest('[data-process-files]');
    if(!btn)return;
    e.preventDefault();e.stopPropagation();
    const files=(window.__novaFiles&&window.__novaFiles.length)?window.__novaFiles.slice():[...($('#fileInput')?.files||[])];
    if(!files.length){toast('请先添加文件到队列');return}
    const detail=document.querySelector('[data-detail-format].selected');
    let key=null;
    if(detail)key='detail-'+detail.dataset.detailFormat;
    else{const opt=document.querySelector('.converter-options .option-card.selected');if(opt)key='work-'+opt.dataset.output}
    const ep=EP[key];
    if(!ep){toast('该转换类型即将上线；当前已支持：PDF→Word、PDF→Excel、合并/拆分/压缩 PDF');return}
    const pdfs=files.filter(f=>/\.pdf$/i.test(f.name));
    if(!pdfs.length){toast('请先添加 PDF 文件');return}
    if(ep==='/api/fx/pdf-merge'){
      if(pdfs.length<2){toast('合并至少需要两个 PDF 文件');return}
      const fd=new FormData();pdfs.forEach(f=>fd.append('files',f));
      const sws=document.querySelectorAll('.settings-row .switch');
      if(sws[2]&&sws[2].getAttribute('aria-checked')==='true')fd.append('opts',JSON.stringify({compress:'true'}));
      pdfs.forEach(f=>stat(f.name,'处理中…'));
      runOne(fd,ep,FB[ep],'合并').then(ok=>{if(ok){pdfs.forEach(f=>stat(f.name,'已合并'));toast('合并完成，已开始下载')}});
      return;
    }
    (async()=>{let okc=0;
      for(const f of pdfs){
        stat(f.name,'处理中…');
        const fd=new FormData();fd.append('files',f);
        const ext=ep.slice(-4)==='docx'?'.docx':'.xlsx';
        const ok=await runOne(fd,ep,f.name.replace(/\.pdf$/i,'')+ext,key.indexOf('Word')>-1?'PDF→Word':'PDF→Excel');
        stat(f.name,ok?'完成':'失败');if(ok)okc++;
      }
      if(okc)toast(okc+' 个文件转换完成，已开始下载');
    })();
  },true);
})();





function novaLogin(e){
  var em=document.querySelector("#email"),pw=document.querySelector("#password");
  var say=function(m,ok){try{toast(m,ok?"good":"error");return}catch(_){}
    var d=document.createElement("div");d.textContent=m;
    d.style.cssText="position:fixed;top:22px;left:50%;transform:translateX(-50%);background:"+(ok?"#188a54":"#d64545")+";color:#fff;padding:11px 18px;border-radius:10px;font-size:13px;z-index:99999;box-shadow:0 8px 24px rgba(0,0,0,.18)";
    document.body.appendChild(d);setTimeout(function(){d.remove()},2600);};
  if(!em.value.trim()||!pw.value){say("请输入用户名和密码");return}
  fetch("/api/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:em.value.trim(),password:pw.value})}).then(function(r){return r.json().then(function(j){return{ok:r.ok,j:j}})}).then(function(x){
    if(x.ok){try{localStorage.setItem("novaUser",JSON.stringify({name:x.j.username||em.value.trim(),role:x.j.role||""}))}catch(_){}
      say("登录成功，正在进入工作空间",true);setTimeout(function(){location.href="workspace.html"},600)}
    else{say((x.j&&(x.j.error||x.j.message))||"登录失败，请检查用户名和密码")}
  }).catch(function(){say("网络错误，请稍后重试")});
}

(function(){
  function who(){try{return JSON.parse(localStorage.getItem("novaUser")||"null")}catch(e){return null}}
  function fmt(v){var s=String(v==null?"":v);var m=/^([0-9]{4}-[0-9]{2}-[0-9]{2})T([0-9]{2}:[0-9]{2})/.exec(s);if(m)return m[1]+" "+m[2];try{var n=+s;if(n>1e12)return new Date(n).toLocaleString("zh-CN",{hour12:false});if(n>1e9)return new Date(n*1000).toLocaleString("zh-CN",{hour12:false})}catch(e){}return s}
  function esc(s){return String(s==null?"":s).replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
  var TN={"fx:pdf-merge":"PDF 合并","fx:pdf-split":"PDF 拆分","fx:pdf-compress":"PDF 压缩","fx:pdf-to-docx":"PDF 转 Word","fx:pdf-to-xlsx":"PDF 转 Excel","t:csv-clean":"CSV 清洗","t:img-process":"图片处理","t:xlsx-profile":"Excel 剖析"};
  function toolName(t){return TN[t]||(t.indexOf("workflow:")===0?"工作流 · "+t.slice(9):t)}
  function rowHTML(nm,meta,ext){return '<div class="recent-row"><div class="file-icon">'+ext+'</div><div class="file-meta"><strong>'+nm+'</strong><span>'+meta+'</span></div></div>'}
  function paint(){
    var nameEl=document.getElementById("pf-name");if(!nameEl)return;
    var u=who();
    if(u){var a=document.getElementById("pf-avatar");if(a)a.textContent=(u.name||"N").charAt(0).toUpperCase();nameEl.textContent=u.name;var m=document.getElementById("pf-mail");if(m)m.textContent=u.name+"@nova.local · 已登录"}
    var right=nameEl.closest("section").nextElementSibling;if(!right)return;
    var sec=document.createElement("div");sec.style.cssText="margin-top:20px;border-top:1px solid #e9eef7;padding-top:18px";
    sec.innerHTML='<div class="panel-head"><div><h3>处理历史</h3><p>最近 8 条真实操作记录（/api/history）。</p></div></div><div id="pf-hist-list"><p class="muted small">加载中…</p></div>';
    right.appendChild(sec);
    fetch("/api/history").then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(list){
      var box=document.getElementById("pf-hist-list");if(!box)return;
      if(!list||!list.length){box.innerHTML='<p class="muted small">暂无记录——去文件工作台合并一次 PDF 再回来看。</p>';return}
      box.innerHTML=list.slice(0,8).map(function(h){var t=h.tool||"";var ext=/pdf/i.test(t)?"PDF":(/csv/i.test(t)?"CSV":"TXT");return rowHTML(esc(toolName(t)),esc(h.output||"")+" · "+esc(fmt(h.at)),ext)}).join("");
    }).catch(function(){var box=document.getElementById("pf-hist-list");if(box)box.innerHTML='<p class="muted small">历史加载失败（未登录或网络问题）。</p>'});
  }
  if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",paint)}else{paint()}
})();

/* 个人中心指标卡接真：处理文件/处理工具/累计耗时，全部来自 /api/history，零演示值 */
(function(){
  function fmtMs(ms){if(!ms)return"0";if(ms<1e3)return ms+"ms";if(ms<6e4)return(ms/1e3).toFixed(1)+"s";return(ms/6e4).toFixed(1)+"min"}
  function setCard(find,rename,val,foot){
    var cs=document.querySelectorAll(".stat-card");
    for(var i=0;i<cs.length;i++){
      var t=cs[i].querySelector(".stat-top span");
      if(t&&t.textContent.indexOf(find)>-1){
        if(rename)t.textContent=rename;
        var v=cs[i].querySelector(".stat-value");if(v)v.textContent=val;
        var f=cs[i].querySelector(".stat-foot");if(f)f.textContent=foot;
      }
    }
  }
  function paint(){
    fetch("/api/history").then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(list){
      list=list||[];var now=Date.now(),n7=0,ms7=0,sum=0,dist={};
      for(var i=0;i<list.length;i++){
        var h=list[i];sum+=(+h.ms||0);dist[h.tool||"?"]=1;
        var t=Date.parse(h.at||"")||0;if(t&&now-t<6048e5){n7++;ms7+=(+h.ms||0)}
      }
      setCard("处理文件",null,String(list.length),n7+" 次操作在近7天");
      setCard("AI 会话","处理工具",String(Object.keys(dist).length),Object.keys(dist).length+" 种工具用过");
      setCard("节省时间","累计耗时",fmtMs(sum),"近7天 "+fmtMs(ms7));
    }).catch(function(){});
  }
  if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",paint)}else{paint()}
})();

/* favicon 兜底：data-URI 内联图标，零网络请求，404 根治 */
(function(){
  if(document.querySelector("link[rel~='icon']"))return;
  var svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><rect width="32" height="32" rx="8" fill="#4f6ef7"/><text x="16" y="22" font-size="17" font-family="Arial,sans-serif" font-weight="bold" fill="#fff" text-anchor="middle">N</text></svg>';
  var l=document.createElement("link");l.rel="icon";l.type="image/svg+xml";
  l.href="data:image/svg+xml,"+encodeURIComponent(svg);
  document.head.appendChild(l);
})();

/* 真机试炼场：12 个文本工具直连 /api/run；卡片诚实徽章：8 可用 8 规划中 */
(function(){
  if(!/tools\.html/.test(location.pathname))return;
  function esc(s){return String(s==null?"":s).replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
  function el(id){return document.getElementById(id)}
  function build(lib,tools){
    var sec=document.createElement("section");sec.id="nova-runner";sec.className="panel";
    sec.style.cssText="margin:19px 0;border:1px solid #e9eef7;border-radius:14px;padding:18px";
    sec.innerHTML='<div class="section-head"><div><h3>真机试炼场</h3><p>文本工具直连后端引擎（/api/run），运行记录自动进入个人中心历史。</p></div></div>'
      +'<div style="display:flex;gap:9px;flex-wrap:wrap;align-items:center;margin:10px 0">'
      +'<select id="nr-tool" style="padding:9px 12px;border:1px solid #e2e8f4;border-radius:10px;background:#fff;font-size:13px;max-width:280px"></select>'
      +'<button id="nr-go" style="padding:9px 18px;border:0;border-radius:10px;background:#4f6ef7;color:#fff;cursor:pointer;font-size:13px">运行</button>'
      +'<span id="nr-ms" class="small muted"></span></div>'
      +'<textarea id="nr-in" placeholder="粘贴输入：CSV、JSON、文本、URL……" style="width:100%;box-sizing:border-box;min-height:110px;padding:12px;border:1px solid #e2e8f4;border-radius:10px;font:12px/1.6 ui-monospace,monospace;resize:vertical"></textarea>'
      +'<pre id="nr-out" style="margin:10px 0 0;padding:12px;min-height:52px;background:#f7f9fe;border:1px solid #e9eef7;border-radius:10px;font:12px/1.6 ui-monospace,monospace;white-space:pre-wrap;word-break:break-all;color:#33415e">输出将显示在这里</pre>';
    lib.parentNode.insertBefore(sec,lib.nextSibling);
    el("nr-tool").innerHTML=tools.map(function(t){return '<option value="'+esc(t.id)+'">'+esc(t.name)+' · '+esc(t.id)+'</option>'}).join("");
    window.__nrSelect=function(id){el("nr-tool").value=id;el("nr-in").focus()};
    el("nr-go").addEventListener("click",function(){
      var id=el("nr-tool").value,input=el("nr-in").value,out=el("nr-out");
      if(!input.trim()){try{toast("请先粘贴输入内容","error")}catch(_){}return}
      out.textContent="运行中…";el("nr-ms").textContent="";
      fetch("/api/run/"+encodeURIComponent(id),{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({input:input,opts:{}})}).then(function(r){return r.json()}).then(function(j){
        if(j&&j.ok!==false&&typeof j.output!=="undefined"){out.textContent=j.output;el("nr-ms").textContent=(j.ms||0)+" ms";try{toast("运行成功","good")}catch(_){}}
        else{out.textContent="出错了："+((j&&j.error)||"未知错误");try{toast("运行失败","error")}catch(_){}}
      }).catch(function(){out.textContent="网络错误";try{toast("网络错误","error")}catch(_){}});
    });
  }
  function badges(){
    var MAP={"JSON 格式化":["可用","#nova-runner","dev.json"],"Base64 / URL 编码":["可用","#nova-runner","dev.encode"],"Markdown 编辑器":["文本版可用","#nova-runner","dev.md"],"PDF 转 Word":["可用","workspace.html",""],"图片压缩与转换":["可用","workspace.html",""],"Excel 数据洞察":["可用","workspace.html",""],"CSV 表格处理":["可用","workspace.html",""],"工作流规划":["可用","workflows.html",""]};
    var cs=document.querySelectorAll(".tool-card");
    for(var i=0;i<cs.length;i++){
      var h=cs[i].querySelector("h3");if(!h)continue;
      var title=(h.childNodes[0]&&h.childNodes[0].textContent||"").trim();
      if(title==="开发者工具箱"||["Word 转 PDF","Excel 分析整理","文本转脑图","文本转流程图","时间戳转换","UUID 生成器","进制转换","图片转 Base64","二维码生成","字数统计","文本去重排序","大小写转换","日期计算器","BMI 计算器"].indexOf(title)>=0)continue;
      var m=MAP[title],tag=document.createElement("span");tag.className="tag";
      if(m){
        tag.textContent=m[0];tag.style.cssText="background:#e8f7ef;color:#188a54;margin-left:6px";h.appendChild(tag);
        cs[i].setAttribute("href",m[1]);
        if(m[1]==="#nova-runner"){(function(id){cs[i].addEventListener("click",function(ev){ev.preventDefault();if(window.__nrSelect)window.__nrSelect(id);var s=el("nova-runner");if(s)s.scrollIntoView({behavior:"smooth"})})})(m[2])}
      }else{
        tag.textContent="规划中";tag.style.cssText="background:#f1f3f9;color:#8a94a8;margin-left:6px";h.appendChild(tag);
        cs[i].addEventListener("click",function(ev){ev.preventDefault();try{toast("该工具规划中，敬请期待")}catch(_){}});
      }
    }
  }
  function init(){
    var lib=document.querySelector(".tool-library");if(!lib)return;
    badges();
    fetch("/api/tools").then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(list){
      var ts=(list||[]).filter(function(t){return t.kind==="text"});
      if(ts.length)build(lib,ts);
    }).catch(function(){});
  }
  if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init)}else{init()}
})();
